CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 BLOB, c1 REAL COLLATE NOCASE, c2 REAL COLLATE NOCASE, c3 INTEGER);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 ANY DEFAULT 'd', c1 REAL UNIQUE, c2 ANY CHECK(c2 IS NULL OR length(c2) < 40)) STRICT;
INSERT OR IGNORE INTO t1(c0, c1, c2) VALUES('a%b', -22.068, NULL);
SELECT date('1999-12-31T23:59:59.999'), time('1999-12-31T23:59:59.999'), datetime('1999-12-31T23:59:59.999', '+1 day'), julianday('1999-12-31T23:59:59.999'), strftime('%j %w %W', '1999-12-31T23:59:59.999'), unixepoch('1999-12-31T23:59:59.999'), timediff('2024-03-01', '2023-01-15');
SELECT date(1700000000), time(1700000000), datetime(1700000000, '+1 year'), julianday(1700000000), strftime('%Y-%m-%d %H:%M:%S', 1700000000), unixepoch(1700000000), timediff('2024-03-01', '2023-01-15');
SELECT date(1700000000), time(1700000000), datetime(1700000000, '-1 month'), julianday(1700000000), strftime('%J', 1700000000), unixepoch(1700000000), timediff('2024-03-01', '2023-01-15');
SELECT date('1999-12-31T23:59:59.999'), time('1999-12-31T23:59:59.999'), datetime('1999-12-31T23:59:59.999', 'weekday 0'), julianday('1999-12-31T23:59:59.999'), strftime('%Y-%m-%d %H:%M:%S', '1999-12-31T23:59:59.999'), unixepoch('1999-12-31T23:59:59.999'), timediff('2024-03-01', '2023-01-15');
SELECT date('1970-01-01'), time('1970-01-01'), datetime('1970-01-01', '+1 year'), julianday('1970-01-01'), strftime('%f', '1970-01-01'), unixepoch('1970-01-01'), timediff('2024-03-01', '2023-01-15');
SELECT date('1970-01-01'), time('1970-01-01'), datetime('1970-01-01', '+1 year'), julianday('1970-01-01'), strftime('%j %w %W', '1970-01-01'), unixepoch('1970-01-01'), timediff('2024-03-01', '2023-01-15');
SELECT a.id, b.id, a.c0, b.id FROM t1 a CROSS JOIN t1 b ORDER BY 1, 2 LIMIT 26;
SELECT count(*) FROM t1 a JOIN t1 b USING(id);
